
--修改债券一级分类为债券分类
UPDATE CFG_DATATABLE_SHOW
SET COLNAME='债券分类', DICTCODE='secType1', SEQNO=5, DISPLAYED=1, FROZEN=0, SORT=1, MAXLEN=100, EXTENDCFG='{"colAlign": "left","supportSearch":"模糊"}', STATUS=1, REMARK1=0, REMARK2=NULL, REMARK3=NULL
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='secType1Name' AND EFFERANGE=0 AND RANGEID='COMM';

--持仓列表表头名称添加单位
UPDATE CFG_DATATABLE_SHOW SET COLNAME='指令可卖出持仓(万元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='etrPledgePrin' AND EFFERANGE=0 AND RANGEID='COMM';
UPDATE CFG_DATATABLE_SHOW SET COLNAME='指令可质押持仓(万元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='etrAvaPledgePrin' AND EFFERANGE=0 AND RANGEID='COMM';
UPDATE CFG_DATATABLE_SHOW SET COLNAME='指令已质押持仓(万元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='etrAlrPledgePrin' AND EFFERANGE=0 AND RANGEID='COMM';
UPDATE CFG_DATATABLE_SHOW SET COLNAME='交易可用券面总额(万元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='trdAvaShareAmt' AND EFFERANGE=0 AND RANGEID='COMM';
UPDATE CFG_DATATABLE_SHOW SET COLNAME='交易在途券面总额(万元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='trdIntransShareAmt' AND EFFERANGE=0 AND RANGEID='COMM';
UPDATE CFG_DATATABLE_SHOW SET COLNAME='账户持仓(万元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='accountPosition' AND EFFERANGE=0 AND RANGEID='COMM';

UPDATE CFG_DATATABLE_SHOW SET COLNAME='持仓成本价(元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='unitCost' AND EFFERANGE=0 AND RANGEID='COMM';
UPDATE CFG_DATATABLE_SHOW SET COLNAME='最新净价(元)'
WHERE PAGECODE='CfetsEtrBondInfo' AND DTCODE='BONDS' AND SPCDCODE='999999' AND COLCODE='price' AND EFFERANGE=0 AND RANGEID='COMM';


